    bg=g[0][0]; h=len(g); w=len(g[0])
    out=[[bg]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and i+1<h:
                out[i+1][j]=g[i][j]
    return out
